Given a query {query}, which of the following two passages is more relevant to the query?

Passage A: {document1}

Passage B: {document2}

Output Passage A or Passage B:

def receive_permutation(window, response):
    digits = ''.join(c if c.isdigit() else ' ' for c in response)
    ids = [int(x) - 1 for x in digits.split()]
    seen = []
    for i in ids:
        if i not in seen and 0 <= i < len(window):
            seen.append(i)
    seen += [i for i in range(len(window)) if i not in seen]
    return [window[i] for i in seen]
